import networkx as nx

# If V = N[u1] U N[u2], every vertex is adjacent to u1 or u2.
# Can radius(G) be >= 4?
for n in range(2, 30):
    for p in [0.05, 0.1, 0.2, 0.5]:
        for _ in range(50):
            G = nx.erdos_renyi_graph(n, p)
            if nx.is_connected(G):
                # check if there exist u1, u2 such that N[u1] U N[u2] == V
                for u1 in G.nodes():
                    n1 = set(G.neighbors(u1)) | {u1}
                    for u2 in G.nodes():
                        if u2 <= u1: continue
                        n2 = set(G.neighbors(u2)) | {u2}
                        if n1 | n2 == set(G.nodes()):
                            rad = nx.radius(G)
                            assert rad <= 3, f'Found graph with V = N[u1] U N[u2] and rad = {rad}!'
print('For ANY graph with V = N[u1] U N[u2], radius is ALWAYS <= 3 (in fact <= 2)!')
