                    valid = False
                    break
        if not valid:
            continue
        W = sum(f)
        # Check if there exists v and k such that k + (n - |B_k(v)|) + 1 <= W
        # B_k(v) is the set of vertices at distance <= k from v
        found = False
        for v in range(n):
            dists = bfs_dist(adj, n, v)
            if len(dists) < n:
