import itertools
from collections import deque

def bfs_diam(adj, n):
    max_d = 0
    for v in range(n):
        dist = {v: 0}
        q = deque([v])
        while q:
            curr = q.popleft()
            for nxt in adj[curr]:
                if nxt not in dist:
                    dist[nxt] = dist[curr] + 1
                    q.append(nxt)
        if len(dist) < n: return None
        max_d = max(max_d, max(dist.values()))
    return max_d

for n in range(2, 9):
    # test paths
    adj = {i: [] for i in range(n)}
    for i in range(n - 1):
        adj[i].append(i + 1); adj[i + 1].append(i)
    diam = bfs_diam(adj, n)
    for f in itertools.product([0, 1, 2], repeat=n):
        valid = True
        for v in range(n):
            if f[v] == 0 and not any(f[u] == 2 for u in adj[v]):
                valid = False; break
        if not valid: continue
        W = sum(f)
        if diam > W:
            print(f'P_{n}: diam={diam} > W={W}! f={f}')
            break
