import networkx as nx
from itertools import product

def roman_domination_number(G):
    n = G.number_of_nodes()
    nodes = list(G.nodes())
    # find min weight of RDF
    min_w = 2 * n
    for assignment in product([0, 1, 2], repeat=n):
        w = sum(assignment)
        if w >= min_w:
            continue
        f = dict(zip(nodes, assignment))
        valid = True
        for v in nodes:
            if f[v] == 0:
                if not any(f[u] == 2 for u in G.neighbors(v)):
                    valid = False
                    break
        if valid:
            min_w = w
    return min_w

# Check tight graphs
tight = []
